import SiteProject from "../models/SiteProject.js";
import { getMimeType } from "../services/fileManagementService.js";

/**
 * Get all sites generated by the logged in user
 */
export const getUsersGeneratedSiteData = async (req, res, next) => {
  try {
    const sites = await SiteProject.find({ email: req.user.email })
      .select("-revisions") // Exclude heavy revisions array from list view
      .sort({ createdAt: -1 });
    res.json(sites);
  } catch (error) {
    next(error);
  }
};

/**
 * Get all sites (Admin only)
 */
export const getAllSiteData = async (req, res, next) => {
  try {
    const sites = await SiteProject.find()
      .select("-revisions")
      .sort({ createdAt: -1 });
    res.json(sites);
  } catch (error) {
    next(error);
  }
};

/**
 * Get single site details by ID
 */
export const getSiteById = async (req, res, next) => {
  try {
    const { id } = req.params;
    const site = await SiteProject.findById(id);
    if (!site) {
      return res.status(404).json({ error: "Project not found" });
    }
    res.json(site);
  } catch (error) {
    next(error);
  }
};

/**
 * Serve individual files directly from MongoDB for live browser preview
 * Handles /api/preview/:id/:filename?
 */
export const servePreviewFile = async (req, res, next) => {
  const { id, filename } = req.params;
  const targetFile = filename || "index.html";

  try {
    const site = await SiteProject.findById(id);
    if (!site || !site.activeFiles || site.activeFiles.length === 0) {
      return res.status(404).send("<h3>Project not found</h3>");
    }

    const file = site.activeFiles.find(
      (f) => f.name.toLowerCase() === targetFile.toLowerCase()
    );

    if (!file) {
      return res.status(404).send(`<h3>File '${targetFile}' not found in project</h3>`);
    }

    // Increment view count if index.html
    if (targetFile === "index.html") {
      SiteProject.findByIdAndUpdate(id, { $inc: { viewCount: 1 } }).catch(() => {});
    }

    const mime = file.mimeType || getMimeType(targetFile);
    res.setHeader("Content-Type", mime);
    res.setHeader("Cache-Control", "public, max-age=300"); // 5 mins cache
    return res.send(file.content);
  } catch (error) {
    console.error("Preview serving error:", error);
    next(error);
  }
};
